<script setup lang="ts">import {ref} from 'vue';import {supabase} from '../lib/supabase';const password=ref(''),confirm=ref(''),message=ref(''),error=ref(''),busy=ref(false);async function change(){message.value='';error.value='';if(password.value.length<10){error.value='Use at least 10 characters.';return}if(password.value!==confirm.value){error.value='Passwords do not match.';return}busy.value=true;try{const {error:e}=await supabase.auth.updateUser({password:password.value});if(e)throw e;message.value='Password changed successfully.';password.value='';confirm.value=''}catch(e:any){error.value=e.message}finally{busy.value=false}}</script>
<template><section class="max-w-2xl"><h1 class="text-3xl font-bold">My account</h1><div class="panel p-6 mt-6"><h2 class="font-semibold">Change password</h2><form class="grid gap-4 mt-5" @submit.prevent="change"><label class="text-sm">New password<input v-model="password" type="password" minlength="10" class="field mt-1" required autocomplete="new-password"></label><label class="text-sm">Confirm new password<input v-model="confirm" type="password" minlength="10" class="field mt-1" required autocomplete="new-password"></label><p v-if="error" class="text-sm text-red-600">{{error}}</p><p v-if="message" class="text-sm text-green-700">{{message}}</p><button class="btn btn-primary justify-self-start" :disabled="busy">{{busy?'Updating…':'Update password'}}</button></form></div></section></template>
